#include <stdio.h>
#include <stdlib.h>

#define VERTICES 6
#define MAX_EDGES 9
#define MST_SIZE (VERTICES-1)

static int parent[VERTICES];

static int find_set(int v) {
    if (parent[v] != v)
        parent[v] = find_set(parent[v]);
    return parent[v];
}

static void union_set(int a, int b) {
    int ra = find_set(a);
    int rb = find_set(b);
    if (ra != rb)
        parent[ra] = rb;
}

typedef struct { int a, b, w; } Edge;

static int cmp_edge(const void *p1, const void *p2) {
    const Edge *e1 = (const Edge *)p1;
    const Edge *e2 = (const Edge *)p2;
    if (e1->w != e2->w)
        return (e1->w < e2->w) ? -1 : 1;
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) { puts("INVALID_ARGS"); return 0; }
    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n < 0 || n > MAX_EDGES) { puts("INVALID_ARGS"); return 0; }

    Edge edges[MAX_EDGES];
    for (int i = 0; i < n; ++i) {
        if (scanf("%d %d %d", &edges[i].a, &edges[i].b, &edges[i].w) != 3) {
            puts("INVALID_ARGS");
            return 0;
        }
        if (edges[i].a < 0 || edges[i].a >= VERTICES || edges[i].b < 0 || edges[i].b >= VERTICES) {
            puts("INVALID_ARGS");
            return 0;
        }
    }

    for (int i = 0; i < VERTICES; ++i) parent[i] = i;
    qsort(edges, n, sizeof(Edge), cmp_edge);

    Edge mst[MST_SIZE];
    int mst_cnt = 0;
    int total_weight = 0;
    for (int i = 0; i < n && mst_cnt < MST_SIZE; ++i) {
        int ra = find_set(edges[i].a);
        int rb = find_set(edges[i].b);
        if (ra != rb) {
            union_set(ra, rb);
            mst[mst_cnt++] = edges[i];
            total_weight += edges[i].w;
        }
    }

    if (mst_cnt < MST_SIZE) { puts("DISCONNECTED"); return 0; }

    printf("weight=%d edges=", total_weight);
    for (int i = 0; i < mst_cnt; ++i) {
        printf("%d-%d", mst[i].a, mst[i].b);
        if (i + 1 < mst_cnt) putchar(',');
    }
    putchar('\n');
    return 0;
}
